// LoadScheduleFundingObligations loads the fundingSchedule's ScheduleFundingObligations into the .R struct
func (o *FundingSchedule) LoadScheduleFundingObligations(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.ScheduleFundingObligations = nil
	o.R.Loaded.ScheduleFundingObligations = false

	related, err := o.ScheduleFundingObligations(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.ScheduleFundingSchedule = o
		rel.R.Loaded.ScheduleFundingSchedule = true
	}

	o.R.ScheduleFundingObligations = related
	o.R.Loaded.ScheduleFundingObligations = true
	return nil
}

// LoadScheduleFundingObligations loads the fundingSchedule's ScheduleFundingObligations into the .R struct
func (os FundingScheduleSlice) LoadScheduleFundingObligations(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	fundingObligations, err := os.ScheduleFundingObligations(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ScheduleFundingObligations = nil
		o.R.Loaded.ScheduleFundingObligations = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	fundingScheduleByKey := make(map[uuid.UUID][]*FundingSchedule, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		fundingScheduleByKey[o.ID] = append(fundingScheduleByKey[o.ID], o)
	}

	for _, rel := range fundingObligations {

		if !rel.ScheduleID.Valid {
			continue
		}

		owners, ok := fundingScheduleByKey[rel.ScheduleID.V]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.ScheduleFundingSchedule = o
			rel.R.Loaded.ScheduleFundingSchedule = true

			o.R.ScheduleFundingObligations = append(o.R.ScheduleFundingObligations, rel)

		}
	}

	return nil
}

