// LoadCountScheduleFundingObligations loads the count of ScheduleFundingObligations for a slice in a single batch query
func (os FundingScheduleSlice) LoadCountScheduleFundingObligations(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "uuid[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			FundingObligations.Columns.ScheduleID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(FundingObligations.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(FundingObligations.Columns.ScheduleID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(FundingObligations.Columns.ScheduleID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[uuid.UUID]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.ScheduleFundingObligations = &count
	}

	return nil
}

type fundingScheduleJoins[Q dialect.Joinable] struct {
	typ                        string
	ScheduleFundingObligations modAs[Q, fundingObligationColumns]
	Household                  modAs[Q, householdColumns]
	Pool                       modAs[Q, poolColumns]
	Member                     modAs[Q, memberColumns]
}

func (j fundingScheduleJoins[Q]) aliasedAs(alias string) fundingScheduleJoins[Q] {
	return buildFundingScheduleJoins[Q](buildFundingScheduleColumns(alias), j.typ)
}

func buildFundingScheduleJoins[Q dialect.Joinable](cols fundingScheduleColumns, typ string) fundingScheduleJoins[Q] {
	return fundingScheduleJoins[Q]{
		typ: typ,
		ScheduleFundingObligations: modAs[Q, fundingObligationColumns]{
			c: FundingObligations.Columns,
			f: func(to fundingObligationColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, FundingObligations.NameExpr().As(to.Alias())).On(
						to.ScheduleID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Pool: modAs[Q, poolColumns]{
			c: Pools.Columns,
			f: func(to poolColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Pools.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PoolID),
					))
				}

				return mods
			},
		},
		Member: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MemberID),
					))
				}

				return mods
			},
		},
	}
}
